S7(a){return"\u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0906\u092a\u0915\u0940 \u092e\u093e\u092a\u0940 \u0917\u0908 \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0914\u0930 \u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u0940 \u0917\u0908 \u0938\u092c\u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u0943\u0926\u092f \u0917\u0924\u093f ("+a+" bpm) \u0915\u0947 \u092c\u0940\u091a \u0915\u0947 \u0905\u0902\u0924\u0930 \u0915\u094b \u0915\u0935\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948\u0902\u0964 \u0926\u094b\u0928\u094b\u0902 \u0906\u092a \u092a\u0930 \u092e\u093e\u092a\u0940 \u0917\u0908 \u0939\u0948\u0902\u0964"},
S8(a){return"\u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u0940 \u0917\u0908 \u0938\u092c\u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u0943\u0926\u092f \u0917\u0924\u093f ("+a+" bpm) \u0915\u0947 \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0939\u0948\u0902 \u2014 \u092e\u093e\u092a\u0940 \u0917\u0908, \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u0928\u0939\u0940\u0902\u0964"},
gRR(){return"\u092f\u0947 \u0915\u0948\u0938\u0947 \u0924\u092f \u0939\u094b\u0924\u0947 \u0939\u0948\u0902"},
gRW(){return"\u092f\u0939 \u0915\u093f\u0938\u0938\u0947 \u092c\u0928\u093e \u0939\u0948"},
gRS(){return"\u0906\u092a\u0915\u0940 \u091c\u093e\u0917\u0928\u0947 \u0915\u0940 \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u092a\u0930 \u092c\u0948\u0928\u093f\u0938\u094d\u091f\u0930 TRIMP, 0\u201321 \u0915\u0947 \u092a\u0948\u092e\u093e\u0928\u0947 \u092a\u0930\u0964"},
RT(a){return"\u0907\u0938\u0947 \u092e\u093e\u0928 \u0932\u093f\u090f \u0917\u090f \u0905\u0927\u093f\u0915\u0924\u092e "+a+" bpm \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u0917\u0923\u0928\u093e \u0915\u0940 \u0917\u0908 \u2014 \u092f\u0939 \u0906\u092a\u0915\u0940 \u0909\u092e\u094d\u0930 \u0914\u0930 \u0938\u094d\u091f\u094d\u0930\u0948\u092a \u0938\u0947 \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u0939\u0948, \u092e\u093e\u092a\u093e \u0928\u0939\u0940\u0902 \u0917\u092f\u093e\u0964"},
gRU(){return"\u090a\u092a\u0930 \u0926\u093f\u092f\u093e \u0917\u092f\u093e \u091c\u093c\u094b\u0928 \u092c\u093e\u0930 \u0907\u0938\u0915\u0947 \u092c\u091c\u093e\u092f \u092e\u093e\u092a\u0940 \u0917\u0908 \u090a\u092a\u0930\u0940 \u0938\u0940\u092e\u093e \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0924\u093e \u0939\u0948; \u0938\u094d\u091f\u094d\u0930\u0947\u0928 \u0915\u094b \u0909\u0938 \u092a\u0930 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u093f\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948, \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u0907\u0938\u0938\u0947 \u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u0947 \u0917\u090f \u0938\u092d\u0940 \u0938\u094d\u091f\u094d\u0930\u0947\u0928 \u0938\u094d\u0915\u094b\u0930 \u092b\u093f\u0930 \u0938\u0947 \u0932\u093f\u0916\u0928\u0947 \u092a\u0921\u093c\u0947\u0902\u0917\u0947\u0964"},
gRV(){return"\u0926\u0942\u0938\u0930\u093e \u0906\u0927\u093e\u0930 \u092a\u093f\u091b\u0932\u0940 \u0930\u093e\u0924 \u0915\u0940 \u0906\u092a\u0915\u0940 \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u091c\u093f\u0938 \u0930\u093e\u0924 \u092c\u0948\u0902\u0921 \u091a\u0942\u0915 \u0917\u092f\u093e \u0935\u0939 \u092a\u0942\u0930\u0947 \u0926\u093f\u0928 \u0915\u094b \u092a\u094d\u0930\u092d\u093e\u0935\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948\u0964"},
gKN(){return"\u0939\u0943\u0926\u092f \u0917\u0924\u093f \u091c\u093c\u094b\u0928"},
gKP(){return"\u0906\u092a\u0915\u0947 \u091c\u093c\u094b\u0928"},
