gKD(){return"\u0905\u092d\u0940 \u0924\u0915 \u0915\u094b\u0908 \u092e\u093e\u092a\u0940 \u0917\u0908 \u090a\u092a\u0930\u0940 \u0938\u0940\u092e\u093e \u0928\u0939\u0940\u0902"},
gKC(){return" \u091c\u092c \u0924\u0915 \u0915\u094b\u0908 \u092e\u093e\u092a\u093e \u0928\u0939\u0940\u0902 \u091c\u093e\u0924\u093e, \u0928\u0940\u091a\u0947 \u0926\u093f\u090f \u0917\u090f \u091c\u093c\u094b\u0928 \u0906\u092a\u0915\u0940 \u0909\u092e\u094d\u0930 \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924 \u0939\u0948\u0902\u0964"},
gKB(){return"\u0939\u092e \u0915\u0947\u0935\u0932 \u0935\u0939\u0940 \u0909\u091a\u094d\u091a \u0930\u0940\u0921\u093f\u0902\u0917 \u0917\u093f\u0928\u0924\u0947 \u0939\u0948\u0902 \u091c\u093f\u0938\u0947 \u092c\u0948\u0902\u0921 \u0928\u0947 \u0906\u092a\u0915\u0947 \u091a\u0932\u0924\u0947 \u0938\u092e\u092f 15 \u0938\u0947\u0915\u0902\u0921 \u0924\u0915 \u092c\u0928\u093e\u090f \u0930\u0916\u093e \u0939\u094b\u0964 \u090f\u0915 \u0938\u0947\u0915\u0902\u0921 \u0915\u0940 \u0938\u094d\u092a\u093e\u0907\u0915 \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gKO(){return"\u0905\u092a\u0928\u0947 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u0920\u093f\u0928 \u0938\u0924\u094d\u0930\u094b\u0902 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u092c\u0948\u0902\u0921 \u092a\u0939\u0928\u0947\u0902"},
gKw(){return"\u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u093e \u0917\u092f\u093e \u0909\u091a\u094d\u091a\u0924\u092e"},
guk(){return"bpm"},
Kr(a){return a+" \u0915\u094b"},
Kq(a){return a+" \u0915\u0947 \u0926\u094c\u0930\u093e\u0928"},
gKv(){return"\u092f\u0939 \u0939\u092e\u093e\u0930\u0947 \u0926\u094d\u0935\u093e\u0930\u093e \u092e\u093e\u092a\u093e \u0917\u092f\u093e \u0909\u091a\u094d\u091a\u0924\u092e \u092e\u093e\u0928 \u0939\u0948, \u0915\u094b\u0908 \u0938\u0940\u092e\u093e \u0928\u0939\u0940\u0902 \u2014 \u091c\u0948\u0938\u0947-\u091c\u0948\u0938\u0947 \u092c\u0948\u0902\u0921 \u0915\u0920\u093f\u0928 \u092a\u094d\u0930\u092f\u093e\u0938 \u0926\u0947\u0916\u0924\u093e \u0939\u0948, \u092f\u0939 \u0927\u0940\u0930\u0947-\u0927\u0940\u0930\u0947 \u092c\u0922\u093c\u0924\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0947 \u092a\u0930\u0916\u0928\u0947 \u0915\u0940 \u0915\u094b\u0936\u093f\u0936 \u0928 \u0915\u0930\u0947\u0902\u0964"},
gKF(){return"\u0905\u092d\u0940 \u0924\u0915 \u0915\u094b\u0908 \u091c\u093c\u094b\u0928 \u0928\u0939\u0940\u0902"},
gKA(){return"\u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0905\u0927\u093f\u0915\u0924\u092e \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0939\u0948\u0902, \u0914\u0930 \u0906\u092a\u0915\u0940 \u0909\u092e\u094d\u0930 \u0915\u0947 \u092c\u093f\u0928\u093e \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0928\u093f\u0915\u093e\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0941\u091b \u092d\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gNF(){return"\u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0906\u092a\u0915\u0940 \u0909\u092e\u094d\u0930 \u0938\u0947 \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u0905\u0927\u093f\u0915\u0924\u092e \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0939\u0948\u0902 \u2014 \u0906\u092a \u092a\u0930 \u092e\u093e\u092a\u0940 \u0928\u0939\u0940\u0902 \u0917\u0908 \u0939\u0948\u0902\u0964"},
gKE(){return"\u0915\u094b\u0908 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092f\u0939 \u0928\u0939\u0940\u0902 \u092c\u0924\u093e\u0924\u093e \u0915\u093f \u0905\u092d\u0940 \u0924\u0915 \u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0915\u094d\u092f\u094b\u0902 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964"},
gKj(){return"\u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932 \u092e\u0947\u0902 \u0905\u092a\u0928\u0940 \u0909\u092e\u094d\u0930 \u091c\u094b\u0921\u093c\u0947\u0902"},
Km(a,b,c){return"\u092f\u0939 \u092c\u0948\u0902\u0921 \u0926\u094d\u0935\u093e\u0930\u093e \u0906\u092a \u092a\u0930 \u092e\u093e\u092a\u0947 \u0917\u090f \u0926\u094b \u0906\u0902\u0915\u0921\u093c\u094b\u0902 \u0938\u0947 \u092c\u0928\u0924\u093e \u0939\u0948: \u0906\u092a\u0915\u0940 \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0917\u0924\u093f ("+a+", \u0906\u092a\u0915\u0940 \u092a\u093f\u091b\u0932\u0940 "+b+" \u0930\u093e\u0924\u094b\u0902 \u0915\u093e \u092e\u0927\u094d\u092f \u092e\u093e\u0928) \u0914\u0930 \u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u0940 \u0917\u0908 \u0938\u092c\u0938\u0947 \u0905\u0927\u093f\u0915 \u0917\u0924\u093f ("+c+")\u0964 \u0915\u092e \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0917\u0924\u093f \u091c\u093c\u094b\u0928 1 \u0915\u094b \u091a\u094c\u0921\u093c\u093e \u092c\u0928\u093e\u0924\u0940 \u0939\u0948\u0964 \u092f\u0947 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092c\u0948\u0902\u0921 \u0939\u0948\u0902, \u0906\u092a\u0915\u0940 \u0905\u092a\u0928\u0940 \u092e\u093e\u092a\u0940 \u0917\u0908 \u0938\u0940\u092e\u093e\u090f\u0901 \u0928\u0939\u0940\u0902\u0964"},
Ko(a,b,c){return"\u092f\u0939 \u0905\u092c \u0924\u0915 \u0926\u0947\u0916\u0940 \u0917\u0908 \u0938\u092c\u0938\u0947 \u0905\u0927\u093f\u0915 \u0939\u0943\u0926\u092f \u0917\u0924\u093f ("+a+") \u0938\u0947 \u092c\u0928\u0924\u093e \u0939\u0948\u0964 \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0917\u0924\u093f \u0915\u0940 "+b+" \u0930\u093e\u0924\u094b\u0902 \u0915\u0947 \u092c\u093e\u0926 (\u0906\u092a\u0915\u0947 \u092a\u093e\u0938 \u0905\u092d\u0940 "+c+" \u0939\u0948\u0902) \u0906\u092a\u0915\u0940 \u0935\u093f\u0936\u094d\u0930\u093e\u092e \u0917\u0924\u093f \u092d\u0940 \u0907\u0938\u092e\u0947\u0902 \u091c\u0941\u0921\u093c \u091c\u093e\u090f\u0917\u0940, \u091c\u094b \u0906\u092a\u0915\u0947 \u0905\u0928\u0941\u0930\u0942\u092a \u092c\u0947\u0939\u0924\u0930 \u092c\u0948\u0920\u0947\u0917\u0940\u0964 \u092f\u0947 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092c\u0948\u0902\u0921 \u0939\u0948\u0902, \u0906\u092a\u0915\u0940 \u0905\u092a\u0928\u0940 \u092e\u093e\u092a\u0940 \u0917\u0908 \u0938\u0940\u092e\u093e\u090f\u0901 \u0928\u0939\u0940\u0902\u0964"},
Kp(a){return"\u092f\u0939 "+a+" bpm \u0938\u0947 \u092c\u0928\u0924\u093e \u0939\u0948, \u091c\u094b \u0906\u092a\u0915\u0940 \u0909\u092e\u094d\u0930 \u0938\u0947 \u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 \u0939\u0948, \u0906\u092a \u092a\u0930 \u092e\u093e\u092a\u093e \u0928\u0939\u0940\u0902 \u0917\u092f\u093e \u2014 \u092f\u0939 \u0915\u093f\u0938\u0940 \u092d\u0940 \u0926\u093f\u0936\u093e \u092e\u0947\u0902 20 bpm \u0924\u0915 \u092d\u093f\u0928\u094d\u0928 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u091c\u0948\u0938\u0947 \u0939\u0940 \u092c\u0948\u0902\u0921 \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u0915\u0920\u093f\u0928 \u0938\u0924\u094d\u0930 \u0926\u0947\u0916\u0924\u093e \u0939\u0948, \u0938\u0940\u092e\u093e\u090f\u0901 \u092e\u093e\u092a\u0940 \u0917\u0908 \u090a\u092a\u0930\u0940 \u0938\u0940\u092e\u093e \u092a\u0930 \u091a\u0932\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948\u0902\u0964"},
gKl(){return"\u091c\u093c\u094b\u0928 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u0905\u0927\u093f\u0915\u0924\u092e \u0939\u0943\u0926\u092f \u0917\u0924\u093f \u0915\u0947 \u092a\u094d\u0930\u0924\u093f\u0936\u0924 \u0939\u0948\u0902\u0964"},
